 31 | async function createServer(proxy) {
 32 | 	return {
 33 | 		allowedHosts: [proxy.target.substring(8)],
 34 | 		cors: { origin: proxy.target },
 35 | 		proxy: {
 36 | 			"/api": proxy,
 37 | 			"/env": proxy,
 38 | 			"/media": proxy
 39 | 		},
 40 | 		open: proxy.target + "/panel",
 41 | 		port: 3000,
 42 | 		...(await createCustomServer())
 43 | 	};
 44 | }
